#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Deploy values (host, key path, generated prod secrets) live in .env.deploy,
# which is gitignored. The app's local .env (Gemini key) is only read, never written.
ENV_FILE=".env.deploy"
LOCAL_APP_ENV=".env"
# Mumbai by default (me-central-1 is impaired). Override: REGION=ap-southeast-1 ./scripts/aws-deploy-wizard.sh
REGION="${REGION:-ap-south-1}"
CONSOLE="https://${REGION}.console.aws.amazon.com/ec2/home?region=${REGION}"
REPO_URL="https://github.com/HamzaWaqar82/sift.git"
REPO_BRANCH="main"
REMOTE_DIR="sift"

_ssh() {
  ssh -i "$SSH_KEY_PATH" -o StrictHostKeyChecking=accept-new -o ConnectTimeout=10 "ubuntu@${ELASTIC_IP}" "$@"
}

# _health_wait SECONDS: poll the public health endpoint until 200 or timeout.
_health_wait() {
  local deadline=$((SECONDS + $1))
  while (( SECONDS < deadline )); do
    if curl -fsS --max-time 5 "https://${PUBLIC_HOSTNAME}/api/health" 2>/dev/null; then
      printf '\n'; return 0
    fi
    printf '.'; sleep 5
  done
  printf '\n'; return 1
}

_gen() { openssl rand -hex "$1"; }

run_wizard() {

TOTAL_STAGES=9

banner "Sift: deploy to AWS EC2 (${REGION})"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create an SSH key pair"
open_url "${CONSOLE}#KeyPairs:"
step "Sign in to the AWS account with the credits. Check the region (top right) shows ${REGION}."
step "Click 'Create key pair'. Name: sift-deploy. Type: ED25519. Format: .pem."
step "Click 'Create key pair'. The browser downloads sift-deploy.pem."
ask SSH_KEY_PATH "Full path to the downloaded .pem (e.g. $HOME/Downloads/sift-deploy.pem):"
SSH_KEY_PATH="${SSH_KEY_PATH/#\~/$HOME}"
while [[ ! -f "$SSH_KEY_PATH" ]]; do
  warn "no file at $SSH_KEY_PATH"
  ask SSH_KEY_PATH "Full path to the .pem:"
  SSH_KEY_PATH="${SSH_KEY_PATH/#\~/$HOME}"
done
chmod 400 "$SSH_KEY_PATH"
write_env SSH_KEY_PATH "$SSH_KEY_PATH"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the security group (firewall)"
open_url "${CONSOLE}#SecurityGroups:"
step "Click 'Create security group'. Name: sift-web. Description: Sift web. VPC: the default."
step "Inbound rules → Add rule: Type SSH,   Source 'My IP'."
step "Inbound rules → Add rule: Type HTTP,  Source 'Anywhere-IPv4'."
step "Inbound rules → Add rule: Type HTTPS, Source 'Anywhere-IPv4'."
step "Leave outbound as is. Click 'Create security group'."
note "SSH is limited to your current IP. If your IP changes later, edit this rule."
pause "Press Enter once sift-web exists"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Launch the EC2 instance"
USER_DATA=$(cat <<'UD'
#!/bin/bash
set -eux
# 2 GB swap so the Next.js build fits on a 2 GB instance
fallocate -l 2G /swapfile && chmod 600 /swapfile && mkswap /swapfile && swapon /swapfile
echo '/swapfile none swap sw 0 0' >> /etc/fstab
curl -fsSL https://get.docker.com | sh
usermod -aG docker ubuntu
systemctl enable --now docker
apt-get install -y git
UD
)
say "User data (installs Docker + swap on first boot), copy it from here:"
printf '%s%s%s\n' "$DIM" "$USER_DATA" "$RESET"
if command -v wl-copy >/dev/null 2>&1; then printf '%s' "$USER_DATA" | wl-copy && note "(also copied to your clipboard)"
elif command -v xclip >/dev/null 2>&1; then printf '%s' "$USER_DATA" | xclip -selection clipboard && note "(also copied to your clipboard)"; fi
open_url "${CONSOLE}#LaunchInstances:"
step "Name: sift."
step "AMI: Ubuntu Server 24.04 LTS (64-bit x86)."
step "Instance type: t3.small."
step "Key pair: sift-deploy."
step "Network settings → Edit → 'Select existing security group' → sift-web."
step "Storage: 20 GiB gp3."
step "Advanced details → User data: paste the script above."
step "Click 'Launch instance', then open it and copy the Instance ID (i-...)."
ask EC2_INSTANCE_ID "Instance ID:"
write_env EC2_INSTANCE_ID "$EC2_INSTANCE_ID"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Attach an Elastic IP (stable address across reboots)"
open_url "${CONSOLE}#Addresses:"
step "Click 'Allocate Elastic IP address' → Allocate."
step "Select the new address → Actions → 'Associate Elastic IP address'."
step "Resource type: Instance. Instance: ${EC2_INSTANCE_ID}. Click Associate."
ask ELASTIC_IP "The Elastic IP (e.g. 3.28.10.20):"
until [[ "$ELASTIC_IP" =~ ^[0-9]{1,3}(\.[0-9]{1,3}){3}$ ]]; do
  warn "that doesn't look like an IPv4 address"
  ask ELASTIC_IP "The Elastic IP:"
done
write_env ELASTIC_IP "$ELASTIC_IP"
write_env PUBLIC_HOSTNAME "sift-${ELASTIC_IP//./-}.sslip.io"
note "Public URL will be https://${PUBLIC_HOSTNAME}"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Check the server is ready"
say "Waiting for SSH and for first-boot setup (Docker install) to finish. This can take 2–4 minutes."
until _ssh true 2>/dev/null; do printf '.'; sleep 5; done; printf '\n'
_ssh 'cloud-init status --wait >/dev/null; docker --version && docker compose version && free -h | grep -i swap'
pause "Docker and swap shown above? Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Put the code on the server"
until curl -fsS --max-time 10 -o /dev/null "https://github.com/HamzaWaqar82/sift"; do
  warn "The GitHub repo isn't reachable yet. Create and push it first (see the README or ask Claude)."
  pause "Press Enter to check again"
done
_ssh "if [ -d ${REMOTE_DIR}/.git ]; then cd ${REMOTE_DIR} && git fetch -q && git checkout -q ${REPO_BRANCH} && git pull -q; else git clone -q -b ${REPO_BRANCH} ${REPO_URL} ${REMOTE_DIR}; fi && cd ${REMOTE_DIR} && git log --oneline -1"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Write the production .env on the server"
say "Generating strong secrets (kept on re-runs so the database password never changes)."
write_env POSTGRES_PASSWORD   "$(_existing POSTGRES_PASSWORD   || _gen 24)"
write_env SESSION_SECRET      "$(_existing SESSION_SECRET      || _gen 32)"
write_env WEBHOOK_SECRET      "$(_existing WEBHOOK_SECRET      || _gen 32)"
# One sign-in password per seeded account.
write_env SEED_PASSWORD_ADMIN "$(_existing SEED_PASSWORD_ADMIN || _gen 12)"
write_env SEED_PASSWORD_ALICE "$(_existing SEED_PASSWORD_ALICE || _gen 12)"
write_env SEED_PASSWORD_BEN   "$(_existing SEED_PASSWORD_BEN   || _gen 12)"
write_env SEED_PASSWORD_CHLOE "$(_existing SEED_PASSWORD_CHLOE || _gen 12)"
write_env SEED_PASSWORD_DEV   "$(_existing SEED_PASSWORD_DEV   || _gen 12)"
GEMINI_API_KEY=$(ENV_FILE="$LOCAL_APP_ENV" _existing GEMINI_API_KEY || true)
if [[ -n "$GEMINI_API_KEY" ]]; then
  note "Using GEMINI_API_KEY from your local ${LOCAL_APP_ENV} (not copied into ${ENV_FILE})."
else
  ask_secret GEMINI_API_KEY "Paste the Gemini API key:"
fi
# Sent over SSH stdin, so secrets never appear in a command line or process list.
_ssh "umask 077 && cat > ${REMOTE_DIR}/.env" <<PRODENV
POSTGRES_USER=sift
POSTGRES_PASSWORD=${POSTGRES_PASSWORD}
POSTGRES_DB=sift
GEMINI_API_KEY=${GEMINI_API_KEY}
GEMINI_MODEL=gemini-3.5-flash-lite
AI_DAILY_CAP=450
AI_RPM_LIMIT=12
WEBHOOK_SECRET=${WEBHOOK_SECRET}
SESSION_SECRET=${SESSION_SECRET}
SEED_PASSWORD_ADMIN=${SEED_PASSWORD_ADMIN}
SEED_PASSWORD_ALICE=${SEED_PASSWORD_ALICE}
SEED_PASSWORD_BEN=${SEED_PASSWORD_BEN}
SEED_PASSWORD_CHLOE=${SEED_PASSWORD_CHLOE}
SEED_PASSWORD_DEV=${SEED_PASSWORD_DEV}
PUBLIC_HOSTNAME=${PUBLIC_HOSTNAME}
PRODENV
_ssh "ls -l ${REMOTE_DIR}/.env"
note "The webhook secret and seed passwords are also in ${ENV_FILE} for the demo."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Start the stack and check HTTPS"
say "Building and starting (first build takes ~5–10 minutes on a t3.small)."
_ssh "cd ${REMOTE_DIR} && docker compose -f compose.prod.yaml up -d --build"
say "Waiting for https://${PUBLIC_HOSTNAME}/api/health (certificate is issued on first request)"
if _health_wait 240; then
  printf '  %s✓ healthy over HTTPS%s\n' "$GREEN" "$RESET"
  echo | openssl s_client -connect "${ELASTIC_IP}:443" -servername "${PUBLIC_HOSTNAME}" 2>/dev/null \
    | openssl x509 -noout -issuer -enddate | sed 's/^/  /'
else
  warn "Not healthy yet. Caddy log tail:"
  _ssh "cd ${REMOTE_DIR} && docker compose -f compose.prod.yaml logs --tail=30 caddy app" || true
  note "Common causes: port 80/443 not open in sift-web, or a Let's Encrypt rate limit on sslip.io."
  SKIPPED+=("HTTPS health check: re-run the wizard after fixing (it resumes with saved values)")
  pause "Press Enter to continue anyway"
fi

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Reboot test (URL must come back by itself)"
if confirm "Reboot the instance now?"; then
  _ssh "sudo reboot" || true
  sleep 20
  say "Waiting for the app to come back"
  if _health_wait 300; then
    printf '  %s✓ back up after reboot at https://%s%s\n' "$GREEN" "$PUBLIC_HOSTNAME" "$RESET"
  else
    warn "Did not come back within 5 minutes."
    SKIPPED+=("Reboot survival check failed: inspect 'docker compose -f compose.prod.yaml ps' on the server")
  fi
else
  SKIPPED+=("Reboot survival test (run: ssh in, sudo reboot, then curl https://${PUBLIC_HOSTNAME}/api/health)")
fi

finish
note "Live URL: https://${PUBLIC_HOSTNAME}"
note "SSH:      ssh -i ${SSH_KEY_PATH} ubuntu@${ELASTIC_IP}"
note "Update:   ssh in, then: cd ${REMOTE_DIR} && git pull && docker compose -f compose.prod.yaml up -d --build"
}

run_wizard "$@"; exit
